<?php defined('BASEPATH') OR exit('No direct script access allowed'); ?>
<div class="page-header d-print-none"><div class="container-xl"><div class="row align-items-center"><div class="col"><div class="page-pretitle">Media</div><h2 class="page-title">Media / Tệp</h2><div class="text-secondary mt-1">Các tệp đã tải lên từ editor và các biểu mẫu nội dung.</div></div></div></div></div>
<div class="page-body"><div class="container-xl"><div class="card"><div class="card-body"><div class="row row-cards"><?php if (empty($files)): ?><div class="empty"><p class="empty-title">Chưa có tệp nào</p></div><?php else: ?><?php foreach ($files as $file): ?><div class="col-sm-6 col-lg-3"><div class="card"><div class="media-preview"><?php if ($file['is_image']): ?><img src="<?php echo base_url($file['path']); ?>" alt="" loading="lazy"><?php else: ?><span><?php echo html_escape(strtoupper(pathinfo($file['name'], PATHINFO_EXTENSION))); ?></span><?php endif; ?></div><div class="card-body p-2"><div class="text-truncate small" title="<?php echo html_escape($file['name']); ?>"><?php echo html_escape($file['name']); ?></div><div class="text-secondary small"><?php echo number_format($file['size'] / 1024, 1); ?> KB</div><?php if ($canDelete): ?><button type="button" class="btn btn-sm btn-ghost-danger mt-2" data-confirm-url="<?php echo site_url('admin/media/xoa/' . rawurlencode($file['name'])); ?>" data-confirm-text="Xóa tệp này? Nội dung đang dùng tệp có thể bị hỏng."><?php echo admin_icon('trash'); ?> Xóa</button><?php endif; ?></div></div></div><?php endforeach; ?><?php endif; ?></div></div></div></div></div>